'use strict';
// This website preview is deliberately self-contained: no CRM requests, account
// creation, telemetry, local storage, email, file uploads or financial submissions.
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',portfolio:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tasks:'M9 5h12 M9 12h12 M9 19h12 M2 5l2 2 3-4 M2 12l2 2 3-4 M2 19l2 2 3-4',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',tools:'M14 4a6 6 0 0 0-7 7l-5 5 4 4 5-5a6 6 0 0 0 7-7l-4 4-4-4z',document:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',wallet:'M3 5h17v15H3z M3 5V3h14 M14 10h7v5h-7z',chat:'M3 3h18v14H9l-6 4z M7 8h10 M7 12h7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',shield:'M12 2l8 3v7c0 5-8 10-8 10S4 17 4 12V5z M8 11l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.document}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
const properties=[{id:1,address:'19 Maple Street',postcode:'WV1 1AA',rent:1250,service:'Full Management',status:'Let',bedrooms:3,type:'Terraced house',start:'1 September 2026'},{id:2,address:'6 Meadow Close',postcode:'WV2 2BB',rent:1100,service:'Rent Collection',status:'Let',bedrooms:2,type:'Semi-detached house',start:'15 August 2026'},{id:3,address:'28 Oak Lane',postcode:'WV3 3CC',rent:1200,service:'Let Only',status:'Let',bedrooms:3,type:'Detached house',start:'1 July 2026'},{id:4,address:'4 Willow Avenue',postcode:'WV4 4DD',rent:1350,service:'Full Management',status:'Onboarding',bedrooms:3,type:'Semi-detached house',start:'Not started'}];
const tasks=[{id:1,title:'Review your service contract',property:4,detail:'Full Management · Sent 5 October',action:'Review & sign',kind:'signature'},{id:2,title:'Review your tenancy agreement (APT)',property:1,detail:'New tenancy · Sent 6 October',action:'Review & sign',kind:'signature'},{id:3,title:'Provide your identity document',property:0,detail:'A photo ID is needed for your landlord profile',action:'Upload ID',kind:'upload'}];
const documents=[{id:1,title:'Assured Periodic Tenancy (APT)',property:1,type:'Tenancy agreements',date:'1 September 2026',status:'Signed'},{id:2,title:'Full Management service contract',property:1,type:'Service contracts',date:'20 August 2026',status:'Signed'},{id:3,title:'Gas Safety certificate',property:1,type:'Compliance',date:'29 October 2025',status:'Renewal due'},{id:4,title:'Electrical Installation Condition Report',property:2,type:'Compliance',date:'16 October 2021',status:'Renewal due'},{id:5,title:'Energy Performance Certificate',property:1,type:'Compliance',date:'15 March 2024',status:'Current'},{id:6,title:'Completed inventory',property:1,type:'Inventories',date:'1 September 2026',status:'Completed'},{id:7,title:'September landlord statement',property:1,type:'Statements',date:'1 October 2026',status:'Available'},{id:8,title:'Service fee invoice',property:1,type:'Invoices',date:'1 October 2026',status:'Paid'}];
const repairs=[{id:1,title:'Boiler losing pressure',property:1,status:'In progress',reported:'4 October 2026',update:'The contractor is arranging an appointment with the tenant.',source:'Tenant report'},{id:2,title:'Loose garden gate',property:2,status:'Awaiting contractor',reported:'3 October 2026',update:'The office has requested a repair quote.',source:'Office property visit'}];
let page='login',loginTab='signin',propertySearch='',propertyFilter='All services',documentFilter='All documents',documentProperty='all',repairFilter='All',demoDone=new Set(),demoChat=[];
const status=(text,tone='')=>`<span class="status ${tone}">${esc(text)}</span>`;
const propertyName=id=>properties.find(p=>p.id===id)?.address||'Your account';
const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
const row=(title,sub,action,attributes,tag='',i='')=>`<div class="row">${i?`<span class="row-icon">${icon(i)}</span>`:''}<div class="row-body"><strong>${esc(title)}</strong><p>${esc(sub)}</p></div>${tag}${action?`<button ${attributes}>${esc(action)} →</button>`:''}</div>`;
const panel=(title,body,target='')=>`<section class="panel"><header><h2>${title}</h2>${target?`<button data-go="${target}">View all →</button>`:''}</header>${body}</section>`;
const stat=(label,value,sub)=>`<div class="stat"><p>${label}</p><strong>${value}</strong><small>${sub}</small></div>`;
function login(){const signin=loginTab==='signin';return `<main class="login-shell"><section class="login-brand"><img class="login-photo" src="lettings-board.png" alt="Fleming Lettings To Let board outside a row of houses" fetchpriority="high"><div class="login-brand-copy"><div class="eyebrow">Your Fleming Lettings account</div><h1>Your properties.<br>Your peace of mind.</h1><p>Your property, documents and lettings team.<br>All in one place, without any of the hassle.</p><span class="brand-rule" aria-hidden="true"></span></div></section><section class="login-content"><div class="tabs" role="tablist" aria-label="Account"><button role="tab" aria-selected="${signin}" class="${signin?'active':''}" data-login-tab="signin">Sign In</button><button role="tab" aria-selected="${!signin}" class="${!signin?'active':''}" data-login-tab="register">Register</button></div><div class="login-form-area"><h2>${signin?'Welcome back':'Your account starts here'}</h2><p class="login-intro">${signin?'One place for tenants and landlords to stay connected with Fleming Lettings.':'Access for tenants and landlords, with your property information in one place.'}</p><label class="field">${signin?'Email address':'Your name'}<input value="${signin?'morgan@example.com':'Morgan Clarke'}" disabled autocomplete="off"></label><label class="field">${signin?'Password':'Email address'}<input value="${signin?'••••••••••••':'morgan@example.com'}" disabled autocomplete="off"></label><button class="primary" ${signin?'data-go="overview"':'data-action="registration-preview"'}>${signin?'Sign In':'Register'}</button><div class="login-secondary">${signin?'<button data-action="reset-info">Forgot your password?</button>':'<button data-action="support-new">Need help with access?</button>'}</div></div><p class="login-contact">Need to get in touch? <a href="tel:01902212415"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2z"/></svg>01902 212 415</a></p></section></main>`}
function taskRows(){const remaining=tasks.filter(t=>!demoDone.has(t.id));return remaining.length?remaining.map(t=>row(t.title,propertyName(t.property)+' · '+t.detail,t.action,`data-task="${t.id}"`,'','document')).join(''):''}
function progress(){return `<div class="progress-area"><strong>4 Willow Avenue</strong><p>${status('Awaiting APT Signature','amber')}</p><p>Waiting on Riley Harper to sign the agreement.<br>In this stage since 6 October 2026.</p><button data-go="onboarding">View Tenant Journey →</button></div>`}
function overview(){return heading('Welcome back, Morgan','Your portfolio, documents and updates — all in one place.',`<button data-action="support-open">Contact the office</button>`)+`<div class="stats">${stat('Your Portfolio',properties.length+' properties',properties.filter(p=>p.status==='Let').length+' let · '+properties.filter(p=>p.status!=='Let').length+' in progress')}${stat('Monthly rental total','£3,550','Contracted rent across 3 let properties')}${stat('Outstanding Tasks',String(tasks.length-demoDone.size),'Documents to sign and identity checks')}${stat('Maintenance','2 open','Updates from tenants and the office')}</div><div class="banner"><div class="row-body"><strong>Your attention keeps things moving</strong><p>Review your pending agreements and upload the documents the office needs.</p></div><button class="primary" data-go="tasks">View your tasks →</button></div><div class="columns"><div>${panel('Your portfolio',properties.map(p=>row(p.address,`${p.service} · ${money(p.rent)} / month`,'View',`data-property="${p.id}"`,status(portfolioState(p).label,portfolioState(p).tone),'home')).join(''),'portfolio')}${panel('Tenant Journey',progress(),'onboarding')}</div><div>${panel('Outstanding Tasks',taskRows(),'tasks')}${panel('Latest updates',repairs.map(r=>row(r.title,propertyName(r.property)+' · '+r.update,'Track',`data-repair="${r.id}"`,'','tools')).join(''),'maintenance')}${panel('Statements & invoices',documents.filter(d=>['Statements','Invoices'].includes(d.type)).map(d=>row(d.title,d.date,'View',`data-document="${d.id}"`,'','document')).join(''),'finance')}</div></div>`}
function portfolio(){const list=properties.filter(p=>(propertyFilter==='All services'||p.service===propertyFilter)&&(p.address+' '+p.postcode).toLowerCase().includes(propertySearch.toLowerCase()));return heading('Your Portfolio','Your properties and their current progress, including newly added properties.')+`<div class="toolbar"><input id="property-search" type="search" aria-label="Search your properties" placeholder="Search your properties…" value="${esc(propertySearch)}"><select id="service-filter" aria-label="Service type">${['All services','Full Management','Rent Collection','Let Only'].map(v=>`<option ${v===propertyFilter?'selected':''}>${v}</option>`).join('')}</select></div><div class="portfolio-legend"><span class="green">Fully Onboarded / Let</span><span class="amber">Waiting / In Progress</span><span class="red">Information Required</span></div><div class="property-grid">${list.map(p=>{const state=portfolioState(p);return `<article class="property-card portfolio-${state.tone}"><div class="property-art">${icon('home')}${status(state.label,state.tone)}</div><div class="details"><h2><button class="property-title-button" data-property="${p.id}">${p.address}</button></h2><p>${p.postcode} · ${p.bedrooms} bedrooms</p><p>${p.service}</p><p class="portfolio-reason">${state.reason}</p><footer><strong>${p.rent?money(p.rent):'Not set'}${p.rent?'<small> / month</small>':''}</strong><button data-property="${p.id}">View Property →</button></footer></div></article>`}).join('')}</div>${!list.length?'<p class="empty">No properties match these filters.</p>':''}`}
function onboarding(){return heading('Property onboarding','Follow each step as the office gets your property ready to let.')+panel('4 Willow Avenue',progress()+`<div class="timeline"><article class="done"><h3>Property details received</h3><p>Address, ownership and service preference recorded · 1 October</p></article><article class="done"><h3>Service arranged</h3><p>Full Management selected and initial property checks completed · 2 October</p></article><article class="done"><h3>Compliance checks</h3><p>Gas, electrical and energy certificates reviewed · 4 October</p></article><article><h3>Marketing preparation</h3><p>Property photographs and the listing are being prepared. The office will ask you to approve the advert.</p></article><article><h3>Viewings and tenant onboarding</h3><p>Follow the next stage here once marketing begins.</p></article></div>`)}
function maintenance(){const list=repairs.filter(r=>repairFilter==='All'||r.status===repairFilter);return heading('Maintenance','Track repairs and upcoming certificate renewals for your properties.')+`<div class="toolbar"><div class="chips">${['All','In progress','Awaiting contractor'].map(s=>`<button data-repair-filter="${s}" class="${s===repairFilter?'active':''}">${s}</button>`).join('')}</div></div><div class="columns"><div>${panel('Maintenance requests',list.length?list.map(r=>row(r.title,propertyName(r.property)+' · Reported '+r.reported,'Track',`data-repair="${r.id}"`,status(r.status,'blue'),'tools')).join(''):'<p class="empty">No repairs match this filter.</p>')}</div><div>${panel('Certificate renewals',row('EICR renewal','6 Meadow Close · Expires 16 October 2026','View','data-document="4"',status('10 days left','amber'),'shield')+row('Gas Safety renewal','19 Maple Street · Expires 29 October 2026','View','data-document="3"',status('23 days left','amber'),'shield'))}</div></div>`}
function docs(){return heading('Documents','Find your agency service contracts, tenancy contracts and property documents.')+`<div class="toolbar"><select id="document-property" aria-label="Document property"><option value="all">All Properties</option>${properties.map(p=>`<option value="${p.id}" ${String(p.id)===documentProperty?'selected':''}>${p.address}</option>`).join('')}</select></div>`+documentLibrary(documentProperty==='all'?null:Number(documentProperty))}
function finance(){const received=receipts.filter(r=>r.received.includes('October')).reduce((n,r)=>n+r.amount,0);return heading('Rent, statements & invoices','Review rental sums and dates received, alongside your landlord statements.')+`<div class="stats">${stat('Contracted monthly rent','£3,550','Across your 3 let properties')}${stat('Rent received this month',money(received),'October 2026 · recorded receipts')}${stat('Fees this month',money(Object.values(monthlyFees).reduce((n,f)=>n+f,0)),'October 2026')}${stat('Rent received to date',money(receipts.reduce((n,r)=>n+r.amount,0)),'Recorded receipts across your properties')}</div><div class="helper">Let Only: rent is paid directly to you after the let. Only payments recorded by the office appear in the payment history.</div><br>`+panel('Recorded rent payments',`<div class="table-wrap"><table><thead><tr><th>Property</th><th>Due date</th><th>Date received</th><th>Amount</th><th>Status</th></tr></thead><tbody>${receipts.map(r=>`<tr><td><button class="text-button" data-property="${r.property}">${propertyName(r.property)}</button></td><td>${r.due}</td><td>${r.received}</td><td class="money">${money(r.amount)}</td><td>${status('Received')}</td></tr>`).join('')}</tbody></table></div>`)+panel('Statements & invoices',documents.filter(d=>['Statements','Invoices'].includes(d.type)).map(d=>row(d.title,d.date+' · '+propertyName(d.property),'View',`data-document="${d.id}"`,'','document')).join(''))}
function account(){return heading('Your Account','Keep your contact details, identity documents and bank details up to date.')+`<div class="account-grid account-revised"><section class="panel contact-panel"><header><h2>${icon('user')}Contact Details</h2></header><div class="form-panel"><div class="contact-fields"><label class="field">Name<input value="Morgan Clarke" disabled></label><label class="field">Email<input value="morgan@example.com" disabled></label><label class="field">Phone<input value="07700 900123" disabled></label></div><button data-action="contact-info">Update Contact Details</button></div></section><section class="panel identity-panel"><header><h2>${icon('shield')}ID&amp;V Documents</h2></header><div class="identity-slots">${identitySlot('primary','Primary ID','Photo identification, such as a passport or driving licence.')}${identitySlot('secondary','Secondary ID','Proof of address, such as a utility bill or bank statement.')}</div></section><section class="panel bank-panel"><header><h2>${icon('wallet')}Bank Details</h2></header><div class="form-panel"><p class="tiny">Payments are made to your verified account.</p><h3>Account ending 1234</h3><p>Account holder: Morgan Clarke</p><button data-action="bank">Request a Bank Change</button><div class="helper">Bank changes require office verification before they are used for payments.</div></div></section></div>`}
function chat(){return heading('Chat with the office','Ask about your properties, documents or an update from the team.')+`<section class="panel chat-layout"><header><h2>Fleming Lettings</h2>${status('Conversation','gray')}</header><div class="chat-messages"><div class="bubble">Hello Morgan, welcome to your landlord portal. How can we help?<small>Office</small></div>${demoChat.map(m=>`<div class="bubble me">${esc(m)}<small>You</small></div>`).join('')}</div><form id="chat-form" class="chat-compose"><label class="visually-hidden" for="chat-message">Message</label><textarea id="chat-message" placeholder="Type your message…" maxlength="1000" required></textarea><button class="primary">Send</button></form></section>`}
const menus=[['overview','home','Overview'],['portfolio','portfolio','My Portfolio'],['tasks','tasks','Outstanding Tasks'],['maintenance','tools','Maintenance'],['finance','wallet','Financials'],['documents','document','Documents'],['support','chat','Support Tickets'],['account','user','My Account']];
function render(){renderHeader();if(page==='login'){app.innerHTML=login();return}const content={overview,portfolio,tasks:officeTasks,onboarding,maintenance,finance,documents:docs,support:supportTickets,property:propertyPage,chat:supportTickets,account}[page]||overview;app.innerHTML=`<div class="shell"><aside class="sidebar"><nav aria-label="Landlord portal">${menus.map(([key,i,title])=>`<button data-go="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(i)}${title}</button>`).join('')}</nav><div class="support-box"><strong>We’re here to help.</strong><p>Your local lettings team.<br><a href="tel:01902212415">01902 212 415</a></p><button data-go="chat">Start a conversation</button></div></aside><div class="workspace"><main class="content">${content()}<footer class="preview-footer">Fleming Lettings & Developments UK Limited</footer></main></div></div>`}
function go(next){if(next==='onboarding'){selectedProperty=4;propertyTab='onboarding';next='property'}if(next==='chat')next='support';if(next.startsWith('property/')){const parts=next.split('/');selectedProperty=Number(parts[1]);propertyTab=['overview','payments','documents','compliance','ownership','onboarding','requests'].includes(parts[2])?parts[2]:'overview';next=properties.some(p=>p.id===selectedProperty)?'property':'portfolio'}if(next==='property'&&propertyTab==='onboarding'&&properties.find(p=>p.id===selectedProperty)?.status==='Let')propertyTab='overview';page=menus.some(m=>m[0]===next)||['login','property'].includes(next)?next:'overview';history.replaceState(null,'','#'+(page==='property'?'property/'+selectedProperty+'/'+propertyTab:page));render();window.scrollTo(0,0)}
function show(title,content){modal.classList.remove("support-dialog");document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-content').innerHTML=content;if(!modal.open)modal.showModal()}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4200)}
function propertyDetail(id){selectedProperty=id;propertyTab='overview';go('property/'+id+'/overview')}
function documentDetail(id){const d=documents.find(x=>x.id===id);if(!d)return;show(d.title,`<div class="document-preview"><div class="eyebrow">Fleming Lettings</div><h3>${d.title}</h3><p>${propertyName(d.property)}<br>${d.date}</p>${complianceDocumentDates(id)}<hr></div><div class="dialog-actions"><button data-close>Close</button><button class="primary" disabled>Download</button></div>`)}
function upload(){show('Upload a document',`<form id="upload-form"><label class="field">Document type<select><option>Photo identification</option><option>Proof of address</option><option>Property document</option></select></label><label class="field">File<input type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Upload Document</button></div></form>`)}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-close')){modal.close();return}
 if(b.dataset.go){modal.close();go(b.dataset.go);return}
 if(b.dataset.loginTab){loginTab=b.dataset.loginTab;render();return}
 if(b.dataset.property){propertyDetail(Number(b.dataset.property));return}
 if(b.dataset.document){documentDetail(Number(b.dataset.document));return}
 if(b.dataset.repairFilter){repairFilter=b.dataset.repairFilter;render();return}
 if(b.dataset.repair){const r=repairs.find(x=>x.id===Number(b.dataset.repair));show(r.title,`${status(r.status,'blue')}<p>${propertyName(r.property)} · ${r.source}<br>Reported ${r.reported}</p><div class="timeline"><article class="done"><h3>Request received</h3><p>The office has logged the issue.</p></article><article class="done"><h3>Latest update</h3><p>${r.update}</p></article><article><h3>Next step</h3><p>The office will update this timeline as work progresses.</p></article></div><button class="primary" data-go="chat">Ask the office about this →</button>`);return}
 if(b.dataset.task){const t=tasks.find(x=>x.id===Number(b.dataset.task));if(t.kind==='office')return officeTask(t);if(t.kind==='upload')return upload();if(t.kind==='listing'){show('Review the property listing',`<p>${propertyName(t.property)} · Marketing preparation</p><button class="primary" data-complete="${t.id}">Mark as Reviewed</button>`);return}show(t.title,`<div class="document-preview"><div class="eyebrow">Signing Request</div><h3>${t.title}</h3><p>${propertyName(t.property)}</p></div><div class="dialog-actions"><button data-close>Back</button><button class="primary" data-complete="${t.id}">Mark as Reviewed</button></div>`);return}
 if(b.dataset.complete){demoDone.add(Number(b.dataset.complete));modal.close();render();toast('Task Reviewed.');return}
 if(b.dataset.download){const d=documents.find(x=>x.id===Number(b.dataset.download)),blob=new Blob([`FLEMING LETTINGS — FICTIONAL SAMPLE\n\n${d.title}\n${propertyName(d.property)}\n${d.date}\n\nPortal design preview only. Not a real agreement, certificate, invoice or statement.\nNo CRM data is included.\n`],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Fleming-sample-'+d.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 switch(b.dataset.action){case'upload':upload();break;case'property-docs':documentProperty=b.dataset.id;documentFilter='All documents';modal.close();go('documents');break;case'reset-info':show('Reset your password','<p>Contact the office for help accessing your account.</p><a href="tel:01902212415">01902 212 415</a><button data-close>Close</button>');break;case'registration-preview':show('Your Fleming Lettings account','<p>Landlords receive access when they sign up. Tenants receive access once fully onboarded.</p><button data-close>Close</button>');break;case'contact-info':show('Update your contact details','<p>Contact the office to update your details.</p><a href="tel:01902212415">01902 212 415</a><button data-close>Close</button>');break;case'bank':show('Request a bank change',`<label class="field">Account name<input value="Morgan Clarke" disabled></label><div class="two-fields"><label class="field">Sort code<input value="00-00-00" disabled></label><label class="field">Account number<input value="00001234" disabled></label></div><div class="dialog-actions"><button data-close>Cancel</button><button class="primary" data-action="bank-preview">Submit Request</button></div>`);break;case'bank-preview':show('Awaiting office verification',`<p>The request would appear on your landlord record for the office to verify using your known contact details. Existing payment details stay in place until approval.</p><button data-close>Close</button>`);break;}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='service-filter'){propertyFilter=el.value;render()}if(el.id==='document-type'){documentFilter=el.value;render()}if(el.id==='document-property'){documentProperty=el.value;render()}});
document.addEventListener('input',event=>{if(event.target.id==='property-search'){const el=event.target,position=el.selectionStart;propertySearch=el.value;render();const next=document.querySelector('#property-search');next.focus();next.setSelectionRange(position,position)}});
document.addEventListener('submit',event=>{if(event.target.id==='upload-form'){event.preventDefault();const file=event.target.querySelector('input[type=file]').files[0];if(file&&file.size>10*1024*1024){toast('Choose a file smaller than 10 MB.');return}demoDone.add(3);modal.close();render();toast('Document Ready for Review.')}if(event.target.id==='chat-form'){event.preventDefault();const text=document.querySelector('#chat-message').value.trim();if(text){demoChat.push(text);render();document.querySelector('#chat-message').focus()}}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()}});
// Property and support journeys use fictional data held only in this page.
let selectedProperty=1,propertyTab='overview',ticketFilter='All',supportMode='chat';
const ticketSeed=[{id:'REQ-1001',subject:'Question about September statement',property:1,category:'Rent & Statements',status:'Open',created:'6 October 2026',messages:[{by:'You',text:'Please explain the management fee on my statement.'},{by:'Office',text:'We are reviewing your statement and will add an update here.'}]}];
let demoTickets=structuredClone(ticketSeed);
const tenants={1:{name:'Alex Taylor',email:'alex.taylor@example.com',phone:'07700 900124'},2:{name:'Jamie Morgan',email:'jamie.morgan@example.com',phone:'07700 900125'},3:{name:'Casey Jordan',email:'casey.jordan@example.com',phone:'07700 900126'}};
const receipts=[{property:1,due:'1 October 2026',received:'1 October 2026',amount:1250},{property:1,due:'1 September 2026',received:'1 September 2026',amount:1250},{property:2,due:'15 September 2026',received:'15 September 2026',amount:1100},{property:2,due:'15 August 2026',received:'15 August 2026',amount:1100}];
const monthlyFees={1:150,2:0,3:0,4:0};
