tasks[0]={id:1,title:'Review the property update',property:4,detail:'Property ready to let · Updated 6 October',action:'Review',kind:'listing'};tasks[1]={id:2,title:'Review your tenancy agreement (APT)',property:4,detail:'Awaiting tenant signature · Sent 6 October',action:'View Agreement',kind:'signature'};tenants[4]={name:'Riley Harper',email:'riley.harper@example.com',phone:'07700 900127'};
function renderHeader(){document.querySelector('.website-header nav').innerHTML=page==='login'?'<a href="https://fleminglettings.co.uk/">Back to website</a>':'<button class="header-account" data-go="account" aria-label="My account: Morgan Clarke"><span class="avatar">MC</span><span>Morgan Clarke<small>My account</small></span></button><button class="logout-button" data-action="logout">Log Out</button>';document.querySelector('#support-launcher').innerHTML=`${chatPromptDismissed?'':`<div class="chat-prompt-wrap"><button class="chat-prompt" data-action="support-open"><span class="online-dot"></span><span><strong>We’re online!</strong><br>Click to chat to us</span></button><button class="chat-prompt-close" data-action="dismiss-chat-prompt" aria-label="Dismiss chat prompt">×</button></div>`}<button class="fleming-launcher" data-action="support-open" aria-label="Open Fleming chat and support"><img src="fleming-icon.png" alt="" width="34" height="34"></button>`}
function propertyPayments(p){const entries=receipts.filter(r=>r.property===p.id);return panel('Rental payments',entries.length?`<div class="table-wrap"><table><thead><tr><th>Due date</th><th>Date received</th><th>Amount</th><th>Status</th></tr></thead><tbody>${entries.map(r=>`<tr><td>${r.due}</td><td>${r.received}</td><td class="money">${money(r.amount)}</td><td>${status('Received')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">${p.service==='Let Only'?'Rent is paid directly to the landlord. No rent receipts are recorded by the office.':'No rent payments have been received for this property yet.'}</p>`)}
function propertyDocuments(p){return documentLibrary(p.id)}
function propertyOnboarding(p){if(p.status==='Let')return '';if(p.id!==4)return propertySetup(p);const stages=[['Holding Deposit Received','Completed · 1 October 2026',true],['Application Submitted','Completed · 2 October 2026',true],['Application Review & Checks','Completed · 5 October 2026',true],['Tenant to Sign APT','Waiting on Riley Harper · Sent 6 October 2026',false],['Final Balance','Next · Payment requested after the agreement stage',false],['Handover Arrangements','Next · Office to confirm with the tenant',false]];return panel('Tenant Journey',`<div class="journey-summary"><div>${status('Awaiting APT Signature','amber')}<h3>Tenant to Sign APT</h3><p>Waiting on <strong>Riley Harper</strong> to sign the tenancy agreement.</p><p class="tiny">In this stage since 6 October 2026 · Last update 6 October 2026</p></div><button data-action="support-new">Ask for an Update</button></div><div class="journey-readiness"><span>${icon('document')} Service Contract Signed</span><span>${icon('home')} Property Ready to Let</span></div><div class="timeline">${stages.map(([title,description,done],index)=>`<article class="${done?'done':index===3?'current':''}"><h3>${title} ${done?'✓':''}</h3><p>${description}</p></article>`).join('')}</div>`)}

function propertyPage(){const p=properties.find(x=>x.id===selectedProperty),total=receipts.filter(r=>r.property===p.id).reduce((sum,r)=>sum+r.amount,0),state=portfolioState(p);const tabs=[['overview','Overview'],['payments','Financials'],['documents','Documents'],['compliance','Compliance'],['ownership','Ownership'],...(p.status==='Let'?[]:[['onboarding',p.id===4?'Tenant Journey':'Property Setup']]),['requests','Requests']];let body='';if(propertyTab==='overview'){body=propertyOverview(p)}else if(propertyTab==='payments'){body=financialSnapshot(p)+propertyPayments(p)+panel('Fees This Month',`<div class="form-panel"><h3>October 2026 · ${money(monthlyFees[p.id])}</h3><p>${monthlyFees[p.id]?'Management fee, including VAT · charged 1 October 2026.':'No fees recorded for this month.'}</p></div>`)}else if(propertyTab==='documents'){body=propertyDocuments(p)}else if(propertyTab==='compliance'){body=propertyCompliance(p)}else if(propertyTab==='ownership'){body=propertyOwnership(p)}else if(propertyTab==='onboarding'){body=propertyOnboarding(p)}else{body=panel('Property Requests',ticketRows(demoTickets.filter(t=>t.property===p.id)))}return `<button class="back-link" data-go="portfolio">← Back to My Portfolio</button>`+heading(p.address,`${p.postcode} · ${p.bedrooms} bedrooms · ${p.service}`,changeMenu(p))+`<div class="stats">${stat('Monthly Rent',p.rent?money(p.rent):'Not Set',p.status==='Let'?'Contracted rent':'Proposed rent')}${stat('Rent Received to Date',p.service==='Let Only'?'Not Recorded':money(total),'Recorded receipts for this tenancy')}${stat('Fees This Month',money(monthlyFees[p.id]),'October 2026')}${stat('Property Status',p.status==='Let'?'Let':p.id===4?'Awaiting APT':state.tone==='red'?'New':'In Progress',state.reason)}</div><nav class="property-tabs" aria-label="Property sections">${tabs.map(([key,title])=>`<button data-property-tab="${key}" aria-current="${propertyTab===key?'page':'false'}" class="${propertyTab===key?'active':''}">${title}</button>`).join('')}</nav>${body}`}
function ticketRows(list){return list.length?list.map(t=>row(t.subject,`${t.id} · ${propertyName(t.property)} · ${t.created}`,'View ticket',`data-ticket="${t.id}"`,status(t.status,t.status==='Closed'?'gray':'amber'),'chat')).join(''):'<p class="empty">No support tickets to show.</p>'}
function supportTickets(){return heading('Support Tickets','Leave a message, track your requests and read updates from the office.',`<button class="primary" data-action="support-new">New support ticket</button>`)+`<div class="toolbar chips">${['All','Open','Closed'].map(s=>`<button data-ticket-filter="${s}" class="${ticketFilter===s?'active':''}">${s}</button>`).join('')}</div>`+panel('Your requests',ticketRows(demoTickets.filter(t=>ticketFilter==='All'||t.status===ticketFilter)))+``}
function newTicket(property=page==='property'?selectedProperty:0){show('Leave a message / support ticket',`<form id="support-ticket-form"><label class="field">Property<select name="property"><option value="0">General / my account</option>${properties.map(p=>`<option value="${p.id}" ${p.id===property?'selected':''}>${p.address}</option>`).join('')}</select></label><label class="field">Topic<select name="category"><option>General enquiry</option><option>Account access</option><option>Rent & statements</option><option>Documents</option><option>Maintenance update</option></select></label><label class="field">Subject<input name="subject" maxlength="120" required></label><label class="field">Message<textarea name="message" maxlength="2000" required></textarea></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Create Ticket</button></div></form>`)}
function viewTicket(id){const t=demoTickets.find(x=>x.id===id);if(!t)return;show(t.id+' · '+t.subject,`${status(t.status,t.status==='Closed'?'gray':'amber')}<p>${esc(propertyName(t.property))} · ${esc(t.category)}<br>${esc(t.created)}</p><div class="ticket-messages">${t.messages.map(m=>`<article><strong>${esc(m.by)}</strong><p>${esc(m.text)}</p></article>`).join('')}</div>${t.status!=='Closed'?`<form id="ticket-reply-form" data-id="${t.id}"><label class="field">Add a message<textarea name="reply" maxlength="2000" required></textarea></label><button class="primary">Add Reply</button> <button type="button" data-close-ticket="${t.id}">Close ticket</button></form>`:''}`)}
function createTicket(subject,property,category,message){const t={id:'REQ-'+(1001+demoTickets.length),subject,property,category,status:'Open',created:new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date()),messages:[{by:'You',text:message}]};demoTickets.unshift(t);return t}
function rentRequest(id){const p=properties.find(x=>x.id===id);show('Request a rent increase',`<p>${p.address}<br>Current monthly rent: <strong>${money(p.rent)}</strong></p><form id="rent-request-form" data-property="${id}"><label class="field">Proposed monthly rent (£)<input name="rent" type="number" min="${p.rent+1}" step="0.01" required></label><label class="field">Preferred date<input name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required></label><label class="field">Message to the office<textarea name="message" maxlength="2000" required></textarea></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Create Request</button></div></form>`)}
function openSupport(){show('Fleming Lettings',`<div class="support-online"><span class="online-dot"></span> We’re online! </div><p>Chat to us, or leave a message for the office.</p><div class="support-actions"><button class="${supportMode==='chat'?'primary':''}" data-support-mode="chat">Live chat</button><button data-action="support-new">Leave a message / ticket</button></div><div class="chat-messages"><div class="bubble">Hello! How can we help?<small>Fleming Lettings</small></div>${demoChat.map(m=>`<div class="bubble me">${esc(m)}<small>You</small></div>`).join('')}</div><form id="widget-chat-form" class="chat-compose"><label class="visually-hidden" for="widget-message">Chat message</label><textarea id="widget-message" name="message" placeholder="Type your message…" maxlength="1000" required></textarea><button class="primary">Send</button></form>`);modal.classList.add('support-dialog')}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.action==='logout'){demoChat=[];demoDone.clear();demoTickets=structuredClone(ticketSeed);loginTab='signin';modal.close();document.querySelector('#toast').classList.remove('visible');go('login')}if(b.dataset.action==='support-open'||b.dataset.supportMode)openSupport();if(b.dataset.action==='support-new')newTicket();if(b.dataset.propertyTab){propertyTab=b.dataset.propertyTab;go('property/'+selectedProperty+'/'+propertyTab)}if(b.dataset.ticketFilter){ticketFilter=b.dataset.ticketFilter;render()}if(b.dataset.ticket)viewTicket(b.dataset.ticket);if(b.dataset.closeTicket){const t=demoTickets.find(x=>x.id===b.dataset.closeTicket);if(t)t.status='Closed';render();viewTicket(b.dataset.closeTicket)}if(b.dataset.rentRequest)rentRequest(Number(b.dataset.rentRequest));});
document.addEventListener('submit',event=>{const form=event.target;if(!['support-ticket-form','ticket-reply-form','widget-chat-form','rent-request-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);if(form.id==='widget-chat-form'){const msg=String(data.get('message')).trim();if(msg){demoChat.push(msg);openSupport();document.querySelector('#widget-message').focus()}return}if(form.id==='ticket-reply-form'){const t=demoTickets.find(x=>x.id===form.dataset.id),reply=String(data.get('reply')).trim();if(t&&reply){t.messages.push({by:'You',text:reply});viewTicket(t.id)}return}let t;if(form.id==='support-ticket-form'){const subject=String(data.get('subject')).trim(),message=String(data.get('message')).trim();if(!subject||!message)return;t=createTicket(subject,Number(data.get('property')),String(data.get('category')),message)}else{const p=properties.find(x=>x.id===Number(form.dataset.property)),amount=Number(data.get('rent'));if(!p||amount<=p.rent)return;t=createTicket('Rent increase request',p.id,'Rent review',`Proposed monthly rent: £${amount.toLocaleString('en-GB',{minimumFractionDigits:2})}. Preferred date: ${data.get('date')}. ${String(data.get('message')).trim()}`)}if(page!=='login')render();viewTicket(t.id);toast('Ticket Created.');});
