documents.push({id:14,title:'Electrical Installation Condition Report',property:1,type:'Compliance',date:'9 October 2021',status:'Renewal due'});
const certificateTypes=[['gas','Gas Safety'],['eicr','EICR'],['epc','EPC']];
const complianceRecords=[{property:1,type:'gas',issued:'2025-10-29',expires:'2026-10-29',docId:3,file:'Gas Safety certificate.pdf'},{property:1,type:'eicr',issued:'2021-10-09',expires:'2026-10-09',docId:14,file:'EICR.pdf'},{property:1,type:'epc',issued:'2024-03-15',expires:'2034-03-15',docId:5,file:'EPC.pdf'},{property:2,type:'eicr',issued:'2021-10-16',expires:'2026-10-16',docId:4,file:'EICR.pdf'}].map(c=>({...c,history:[],source:'Office Record'}));
let pendingCertificate=null;
const complianceSeed=structuredClone(complianceRecords);
const complianceDocumentSeed=structuredClone(documents);
const readableDate=value=>value?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value+'T12:00:00Z')):'Not recorded';
function certificateStatus(c){if(!c)return status('Not on file','gray');const today=new Date(),now=Date.UTC(today.getFullYear(),today.getMonth(),today.getDate()),days=Math.round((Date.parse(c.expires+'T00:00:00Z')-now)/86400000);return status(days<0?`${Math.abs(days)} days overdue`:days===0?'Expires today':days<=30?`${days} days left`:'Current',days<=30?'amber':'')}
function certificateIcon(type){return type==='eicr'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M13 2 4 14h7l-1 8 10-12h-7z"/></svg>':type==='gas'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 2c1 6-5 7-5 11a5 5 0 0 0 10 0c0-3-2-4-2-6-1 2-2 3-3 3 2-3 2-5 0-8z"/></svg>':icon('home')}
function propertyCompliance(p){return panel('Property Compliance',`<div class="compliance-list">${certificateTypes.map(([type,label])=>{const c=complianceRecords.find(x=>x.property===p.id&&x.type===type);return `<article class="certificate"><div class="certificate-heading"><span class="certificate-icon">${certificateIcon(type)}</span><strong>${label}</strong>${certificateStatus(c)}</div><div class="certificate-dates"><div>Issue / inspection date<strong>${readableDate(c?.issued)}</strong></div><div>${type==='eicr'?'Next inspection due':'Expiry date'}<strong>${readableDate(c?.expires)}</strong></div></div>${c?`<p class="certificate-file">${esc(c.file)} · ${esc(c.source)}</p>`:''}<div class="certificate-actions">${c?`<button data-document="${c.docId}">View / download</button>`:''}<button data-certificate-upload="${type}" data-certificate-property="${p.id}">${c?'Upload Replacement':'Upload Certificate'}</button>${c?.history.length?`<button data-certificate-history="${type}" data-certificate-property="${p.id}">History (${c.history.length})</button>`:''}</div></article>`}).join('')}</div>`)}
function complianceDocumentDates(id){const c=complianceRecords.find(x=>x.docId===id);return c?`<p><strong>Issue / inspection date:</strong> ${readableDate(c.issued)}<br><strong>${c.type==='eicr'?'Next inspection due':'Expiry date'}:</strong> ${readableDate(c.expires)}</p>`:''}
function uploadCertificate(property,type){const c=complianceRecords.find(x=>x.property===property&&x.type===type),label=certificateTypes.find(t=>t[0]===type)[1];pendingCertificate=null;show(`${c?'Replace':'Upload'} ${label} Certificate`,`<p>${propertyName(property)}</p><form id="certificate-form" data-property="${property}" data-type="${type}"><label class="field">Certificate file<input name="file" type="file" accept=".pdf,.jpg,.jpeg,.png" required></label><label class="field">Issue / inspection date<input name="issued" type="date" required></label><label class="field">${type==='eicr'?'Next inspection due':'Expiry date'}<input name="expires" type="date" required></label><p class="error" id="certificate-error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Review ${c?'replacement':'certificate'}</button></div></form>`)}
function reviewCertificate(form){const file=form.elements.file.files[0],issued=form.elements.issued.value,expires=form.elements.expires.value,error=document.querySelector('#certificate-error');if(!file||!issued||!expires)return;if(!/\.(pdf|jpe?g|png)$/i.test(file.name)){error.textContent='Choose a PDF, JPG or PNG certificate.';return}if(file.size>10*1024*1024){error.textContent='Choose a file smaller than 10 MB.';return}if(expires<=issued){error.textContent='The expiry or next inspection date must be after the issue date.';return}pendingCertificate={property:Number(form.dataset.property),type:form.dataset.type,issued,expires,file:file.name};const current=complianceRecords.find(c=>c.property===pendingCertificate.property&&c.type===pendingCertificate.type);show('Review Certificate Replacement',`<div class="certificate-review"><strong>${propertyName(pendingCertificate.property)}</strong><dl><dt>New file</dt><dd>${esc(file.name)}</dd><dt>Issue date</dt><dd>${readableDate(issued)}</dd><dt>Expiry / next due</dt><dd>${readableDate(expires)}</dd></dl>${current?`<p>Replaces: ${esc(current.file)}<br>Previous due date: ${readableDate(current.expires)}</p>`:''}</div><p>The new certificate will become the current record. ${current?'The previous certificate and dates will remain in the history.':''}</p><div class="dialog-actions"><button data-close>Cancel</button><button class="primary" data-action="confirm-certificate">Confirm Replacement</button></div>`)}
function confirmCertificate(){if(!pendingCertificate)return;const next=pendingCertificate,existing=complianceRecords.find(c=>c.property===next.property&&c.type===next.type);let docId;if(existing){const {history,...previous}=existing;history.unshift(previous);docId=existing.docId;Object.assign(existing,next,{source:'Your Upload'})}else{docId=Math.max(...documents.map(d=>d.id))+1;complianceRecords.push({...next,docId,history:[],source:'Your Upload'});documents.push({id:docId,property:next.property,type:'Compliance',title:certificateTypes.find(t=>t[0]===next.type)[1]+' certificate'})}const d=documents.find(d=>d.id===docId);d.date=readableDate(next.issued);d.status=Date.parse(next.expires)<Date.now()?'Review due':'Current';pendingCertificate=null;modal.close();render();toast('Certificate Replaced. Previous Version Retained.')}
function certificateHistory(property,type){const c=complianceRecords.find(x=>x.property===property&&x.type===type);if(!c)return;show('Certificate History',`<p>${propertyName(property)} · ${certificateTypes.find(t=>t[0]===type)[1]}</p>${[{...c,current:true},...c.history].map(v=>`<article class="certificate-history"><strong>${v.current?'Current certificate':'Previous certificate'}</strong><p>${esc(v.file)}</p><p>Issued ${readableDate(v.issued)}<br>Expiry / next inspection ${readableDate(v.expires)}</p></article>`).join('')}`)}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.certificateUpload)uploadCertificate(Number(b.dataset.certificateProperty),b.dataset.certificateUpload);if(b.dataset.certificateHistory)certificateHistory(Number(b.dataset.certificateProperty),b.dataset.certificateHistory);if(b.dataset.action==='confirm-certificate')confirmCertificate();if(b.dataset.action==='logout'){complianceRecords.splice(0,complianceRecords.length,...structuredClone(complianceSeed));documents.splice(0,documents.length,...structuredClone(complianceDocumentSeed));pendingCertificate=null;}});
document.addEventListener('submit',event=>{if(event.target.id==='certificate-form'){event.preventDefault();reviewCertificate(event.target)}});
let chatPromptDismissed=false,pendingEvidence=null,documentCategory='All Documents';
properties.push({id:5,address:'12 Birch Road',postcode:'WV5 5EE',rent:0,service:'Full Management',status:'New',bedrooms:2,type:'Terraced house',start:'Not started'});monthlyFees[5]=0;
const identityRecords={primary:{file:'Passport.pdf',type:'Passport',status:'Verified',date:'1 October 2026'},secondary:{file:null,type:'Proof of Address',status:'Required',date:null}};
const ownershipRecords=Object.fromEntries(properties.map(p=>[p.id,p.id===5?{file:null,type:null,status:'Required',date:null}:{file:'Title register.pdf',type:'Title Deed / Land Registry',status:'Verified',date:'2 October 2026'}]));
const identitySeed=structuredClone(identityRecords),ownershipSeed=structuredClone(ownershipRecords);
function portfolioState(p){if(p.status==='Let')return {tone:'green',label:'Fully Onboarded / Let',reason:'Tenancy active · onboarding complete'};if(p.id===5&&ownershipRecords[p.id]?.status==='Required')return {tone:'red',label:'Information Required',reason:'New property · documents and details needed'};return {tone:'amber',label:'Waiting / In Progress',reason:p.id===4?'Waiting for tenant to sign APT':'Ownership evidence awaiting office review'}}
function identitySlot(key,label,help){const record=identityRecords[key];return `<article class="identity-slot"><div class="evidence-title"><h3>${label}</h3>${status(record.status,record.status==='Verified'?'green':record.status==='Required'?'red':'amber')}</div><p>${help}</p>${record.file?`<p class="evidence-file">${icon('document')}${esc(record.file)}</p><button data-evidence-view="identity" data-evidence-key="${key}">View Document</button>`:''}<button data-evidence-upload="identity" data-evidence-key="${key}">${record.file?'Replace':'Upload'} ${label}</button></article>`}
function propertyOwnership(p){const record=ownershipRecords[p.id];return panel(icon('home')+'<span>Property Ownership</span>',`<div class="form-panel ownership-evidence"><div class="evidence-title"><h3>Proof of Ownership</h3>${status(record.status==='Verified'?'Ownership Verified':record.status,record.status==='Verified'?'green':record.status==='Required'?'red':'amber')}</div>${record.file?`<p class="evidence-file">${icon('document')}${esc(record.file)}</p><p class="tiny">${esc(record.type)} · ${esc(record.date||'')}</p><button data-evidence-view="ownership" data-evidence-key="${p.id}">View Evidence</button>`:''}<button data-evidence-upload="ownership" data-evidence-key="${p.id}">${record.file?'Replace Evidence':'Upload Proof of Ownership'}</button></div>`)}
function propertySetup(p){return panel('Property Setup',`<div class="form-panel"><h3>${portfolioState(p).label}</h3><p>${portfolioState(p).reason}</p></div><div class="timeline"><article class="done"><h3>Property Added</h3><p>Property is visible in your portfolio.</p></article><article class="current"><h3>Proof of Ownership</h3><p>${ownershipRecords[p.id].status==='Required'?'Waiting on you to upload evidence.':'Waiting on the office to verify your evidence.'}</p></article><article><h3>Service Contract</h3><p>Not yet received.</p></article><article><h3>Compliance Documents</h3><p>EPC, EICR and Gas Safety records to be supplied and reviewed.</p></article><article><h3>Ready to Let</h3><p>Pending the required information and office checks.</p></article></div>`)}
function evidenceUpload(kind,key){pendingEvidence=null;const label=kind==='identity'?(key==='primary'?'Primary ID':'Secondary ID'):'Proof of Ownership';show('Upload '+label,`<p>${kind==='ownership'?propertyName(Number(key)):'Your ID&V documents'}</p><form id="evidence-form" data-kind="${kind}" data-key="${key}"><label class="field">Document Type<select name="type">${(kind==='ownership'?['Mortgage Statement','Title Deed / Land Registry','Other Ownership Evidence']:key==='primary'?['Passport','Driving Licence','Other Photo ID']:['Bank Statement','Utility Bill','Other Proof of Address']).map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Document<input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png" required></label><p id="evidence-error" class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Review Document</button></div></form>`)}
function evidenceView(kind,key){const r=kind==='identity'?identityRecords[key]:ownershipRecords[Number(key)];show(kind==='identity'?'ID&V Document':'Proof of Ownership',`<div class="document-preview"><div class="eyebrow">Fleming Lettings</div><h3>${esc(r.type||'Document')}</h3><p>${esc(r.file||'No file')}<br>${kind==='ownership'?propertyName(Number(key)):'Account identity evidence'}</p>${status(r.status,r.status==='Verified'?'green':'amber')}</div><button data-close>Close</button>`)}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.action==='dismiss-chat-prompt'){chatPromptDismissed=true;document.querySelector('.chat-prompt-wrap')?.remove()}if(b.dataset.evidenceUpload)evidenceUpload(b.dataset.evidenceUpload,b.dataset.evidenceKey);if(b.dataset.evidenceView)evidenceView(b.dataset.evidenceView,b.dataset.evidenceKey);if(b.dataset.action==='confirm-evidence'&&pendingEvidence){const r=pendingEvidence.kind==='identity'?identityRecords[pendingEvidence.key]:ownershipRecords[Number(pendingEvidence.key)];r.file=pendingEvidence.file;r.type=pendingEvidence.type;r.status='Awaiting Office Review';r.date=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());pendingEvidence=null;modal.close();render();toast('Document Awaiting Review.')}if(b.dataset.action==='logout'){Object.assign(identityRecords,structuredClone(identitySeed));Object.assign(ownershipRecords,structuredClone(ownershipSeed));pendingEvidence=null;}if(b.dataset.docCategory){documentCategory=b.dataset.docCategory;render()}});
document.addEventListener('submit',event=>{if(event.target.id!=='evidence-form')return;event.preventDefault();const form=event.target,file=form.elements.file.files[0],error=document.querySelector('#evidence-error');if(!file)return;if(!/\.(pdf|jpe?g|png)$/i.test(file.name)||file.size>10*1024*1024){error.textContent='Choose a PDF, JPG or PNG smaller than 10 MB.';return}pendingEvidence={kind:form.dataset.kind,key:form.dataset.key,file:file.name,type:form.elements.type.value};show('Review Document',`<div class="certificate-review"><strong>${esc(pendingEvidence.type)}</strong><p>${esc(file.name)}</p><p>${pendingEvidence.kind==='ownership'?propertyName(Number(pendingEvidence.key)):'Your '+(pendingEvidence.key==='primary'?'Primary':'Secondary')+' ID'}</p></div><p>Status after submission: <strong>Awaiting Office Review</strong>.</p><div class="dialog-actions"><button data-close>Cancel</button><button class="primary" data-action="confirm-evidence">Confirm Document</button></div>`)});
function documentLibrary(propertyId){const categories=[['Agency Service Contracts','Service contracts','document'],['Tenancy Contracts','Tenancy agreements','document'],['Property Documents','property','home']],available=documents.filter(d=>!propertyId||d.property===propertyId);return `<nav class="document-categories" aria-label="Document Categories">${['All Documents',...categories.map(c=>c[0])].map(c=>`<button data-doc-category="${c}" class="${documentCategory===c?'active':''}">${c}</button>`).join('')}</nav>`+categories.filter(c=>documentCategory==='All Documents'||documentCategory===c[0]).map(([title,type,i])=>{const group=available.filter(d=>type==='property'?['Compliance','Inventories'].includes(d.type):d.type===type);let rows=group.map(d=>{const c=complianceRecords.find(c=>c.docId===d.id);return row(d.title,`${propertyId?'':propertyName(d.property)+' · '}${c?'Issued '+readableDate(c.issued)+' · '+(c.type==='eicr'?'Next inspection ':'Expires ')+readableDate(c.expires):d.date}`,'View / Download',`data-document="${d.id}"`,c?certificateStatus(c):status(d.status),'document')}).join('');if(type==='property'){rows+=properties.filter(p=>!propertyId||p.id===propertyId).map(p=>{const r=ownershipRecords[p.id];return row('Proof of Ownership',`${propertyName(p.id)} · ${r.file||'Document required'}`,r.file?'View Evidence':'Upload Evidence',`data-evidence-${r.file?'view':'upload'}="ownership" data-evidence-key="${p.id}"`,status(r.status,r.status==='Verified'?'green':r.status==='Required'?'red':'amber'),'home')}).join('')}return panel(icon(i)+'<span>'+title+'</span>',rows||'<p class="empty">No documents in this category yet.</p>')}).join('')}
Object.assign(paths,{phone:'M5 3h4l2 5-3 2a14 14 0 0 0 6 6l2-3 5 2v4c0 2-2 3-4 2A20 20 0 0 1 3 7c-1-2 0-4 2-4',mail:'M3 5h18v14H3z M3 5l9 7 9-7',calendar:'M4 5h16v16H4z M4 10h16 M8 2v6 M16 2v6'});
const rentInvoices=receipts.map((r,i)=>({...r,id:'RENT-'+(i+1),state:'Paid'}));
const nextRentInvoices={1:{id:'RENT-NEXT-1',property:1,due:'1 November 2026',received:null,amount:1250,state:'Upcoming'},2:{id:'RENT-NEXT-2',property:2,due:'15 October 2026',received:null,amount:1100,state:'Upcoming'}};
function tenancyDuration(p){const starts={1:'2026-09-01',2:'2026-08-15',3:'2026-07-01'},start=starts[p.id]?new Date(starts[p.id]+'T12:00:00'):null,today=new Date();if(!start||today<start)return 'Not Started';let months=(today.getFullYear()-start.getFullYear())*12+today.getMonth()-start.getMonth(),days=today.getDate()-start.getDate();if(days<0){months--;days+=new Date(today.getFullYear(),today.getMonth(),0).getDate()}return [months?months+' '+(months===1?'month':'months'):'',days?days+' '+(days===1?'day':'days'):''].filter(Boolean).join(' ')||'Started Today'}
function serviceSummary(p){const state=portfolioState(p),contract=documents.find(d=>d.property===p.id&&d.type==='Service contracts'),rate=p.id===5?'To Be Agreed':p.service==='Let Only'?'£600 One-off Fee':p.service==='Rent Collection'?'8% of Rent':'12% of Rent';return panel(icon('portfolio')+'<span>Service & Tenancy Details</span>',`<div class="service-summary"><div class="service-bubbles"><span class="service-bubble purple">${icon('shield')}${p.service}</span><span class="service-bubble ${state.tone}">${icon('home')}${state.label}</span><span class="service-bubble ${contract?'green':'red'}">${icon('document')}${contract?'Service Contract Signed':'Service Contract Required'}</span></div><dl class="service-facts"><div><dt>${icon('wallet')}Service Rate</dt><dd>${rate}<small>${p.id===5?'Pending service agreement':'Including VAT'}</small></dd></div><div><dt>${icon('calendar')}Tenancy Start</dt><dd>${p.start}</dd></div><div><dt>${icon('clock')}Length of Tenancy</dt><dd>${tenancyDuration(p)}</dd></div><div><dt>${icon('document')}Tenancy Type</dt><dd>${p.status==='Let'?'Assured Periodic Tenancy':p.id===4?'Proposed Assured Periodic Tenancy':'Not Set'}</dd></div></dl></div>`)}
function tenantSummary(p){const source=tenants[p.id],people=source?(Array.isArray(source)?source:[source]):[];return panel(icon('user')+'<span>'+ (p.status==='Let'?'Tenant Information':'Prospective Tenant')+'</span>',people.length?people.map(t=>`<article class="tenant-profile"><h3>${icon('user')}${esc(t.name)}</h3><div class="tenant-contact"><span>${icon('mail')}<span><small>Email Address</small>${esc(t.email)}</span></span><span>${icon('phone')}<span><small>Phone Number</small>${esc(t.phone)}</span></span></div></article>`).join(''):'<p class="empty">No tenant assigned yet.</p>')}
function financialSnapshot(p){const history=rentInvoices.filter(r=>r.property===p.id).slice(0,4),next=nextRentInvoices[p.id];return panel(icon('wallet')+'<span>Financials Snapshot</span>',`<div class="rent-due-strip"><div><span class="due-label">${next?'Next Rent Invoice':'Rent Invoices'}</span><strong>${next?money(next.amount):p.service==='Let Only'?'Paid Directly to Landlord':'Not Started'}</strong><p>${next?'Due '+next.due:p.service==='Let Only'?'Rent is collected directly by you.':'No rent invoice has been raised yet.'}</p></div>${next?`${status('Upcoming','amber')}<button data-rent-invoice="${next.id}">View Invoice</button>`:''}</div><div class="recent-invoice-heading">Recent Rent Invoices <span>Latest ${history.length} of up to 4</span></div>${history.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Due Date</th><th>Date Received</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${history.map(r=>`<tr><td>${r.id}</td><td>${r.due}</td><td>${r.received||'—'}</td><td class="money">${money(r.amount)}</td><td>${status(r.state,'green')}</td><td><button data-rent-invoice="${r.id}">View</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No recorded rent invoices for this property.</p>'}`)}
function propertyOverview(p){return `<div class="property-overview-top">${tenantSummary(p)}${serviceSummary(p)}</div>${financialSnapshot(p)}<div class="columns"><div>${propertyCompliance(p)}</div><div>${propertyOwnership(p)}</div></div>`}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b?.dataset.rentInvoice)return;const invoice=[...rentInvoices,...Object.values(nextRentInvoices)].find(r=>r.id===b.dataset.rentInvoice);if(!invoice)return;show('Rent Invoice',`<div class="document-preview"><div class="eyebrow">Fleming Lettings</div><h3>${invoice.id}</h3><p>${propertyName(invoice.property)}</p><dl class="property-facts"><dt>Rent Due</dt><dd>${money(invoice.amount)}</dd><dt>Due Date</dt><dd>${invoice.due}</dd><dt>Date Received</dt><dd>${invoice.received||'Not Received'}</dd><dt>Status</dt><dd>${invoice.state}</dd></dl></div><button data-close>Close</button>`)});

const changeOptions=['Request a Rent Review','Request Inspection','End Tenancy','Cancel Services'];
function changeMenu(p){return '<details class="change-menu"><summary>Request a Change <svg class="change-chevron" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 7.5 5 5 5-5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></summary><div>'+changeOptions.map((label,i)=>'<button data-change-request="'+i+'" data-change-property="'+p.id+'">'+icon(['wallet','home','calendar','document'][i])+label+'</button>').join('')+'</div></details>'}
function changeRequest(id,index){const p=properties.find(p=>p.id===id),title=changeOptions[index];if(!p||!title)return;document.querySelector('.change-menu')?.removeAttribute('open');show(title,'<p>'+p.address+'</p><form id="change-request-form" data-property="'+id+'" data-index="'+index+'">'+(index===0?'<p>Current monthly rent: <strong>'+money(p.rent)+'</strong></p><label class="field">Suggested Monthly Rent (£) — Optional<input name="rent" type="number" min="1" step="0.01"></label>':'')+'<label class="field">Preferred Date — Optional<input name="date" type="date"></label><label class="field">Message to the Office<textarea name="message" maxlength="2000" required></textarea></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Create Request</button></div></form>')}
