function officeTasks(){return heading('Outstanding Tasks','Requests from the office, documents to sign and updates on what we are waiting for.')+['Action Required','Waiting on Others'].map(group=>panel(icon(group==='Action Required'?'tasks':'clock')+'<span>'+group+'</span>',tasks.filter(t=>t.category===group).map(t=>'<article class="office-task"><span class="row-icon">'+icon(t.id===4?'shield':t.id===3?'user':'document')+'</span><div class="row-body"><h3>'+t.title+'</h3><p>'+propertyName(t.property)+'</p><small>'+t.detail+'</small><p class="task-waiting">Waiting On: <strong>'+t.waiting+'</strong></p></div>'+status(group==='Action Required'?'Your Action Needed':'Awaiting Update',group==='Action Required'?'amber':'blue')+'<button data-task="'+t.id+'">'+t.action+' →</button></article>').join(''))).join('')}
function officeTask(t){show(t.title,'<p>'+propertyName(t.property)+'</p>'+status('Waiting On: '+t.waiting,t.category==='Action Required'?'amber':'blue')+'<p>'+t.instruction+'</p><p class="tiny">'+t.detail+'</p><div class="dialog-actions"><button data-close>Close</button>'+(t.id===3?'<button class="primary" data-go="account">View ID&V Documents</button>':t.id===2?'<button class="primary" data-go="property/4/onboarding">View Tenant Journey</button>':t.id===4?'<button class="primary" data-go="property/5/compliance">View Compliance</button>':'')+'</div>')}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(b?.hasAttribute('data-change-request'))changeRequest(Number(b.dataset.changeProperty),Number(b.dataset.changeRequest));});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelector('.change-menu')?.removeAttribute('open')});
document.addEventListener('submit',event=>{const f=event.target;if(f.id!=='change-request-form')return;event.preventDefault();const d=new FormData(f),message=String(d.get('message')).trim();if(!message)return;const rent=d.get('rent'),date=d.get('date'),t=createTicket(changeOptions[Number(f.dataset.index)],Number(f.dataset.property),'Property Change',(rent?'Suggested rent: £'+rent+'. ':'')+(date?'Preferred date: '+date+'. ':'')+message);render();viewTicket(t.id);toast('Request Created.');});
